const response = $json;
const contacts = Object.values(response.contacts || {});

const today = new Date();

return contacts
  .filter(contact => {
    const fields = contact.fields?.all || {};
    const nurtureStoppedRaw = fields.ac_nurture_stopped;
    if (nurtureStoppedRaw === true || nurtureStoppedRaw === 1 || nurtureStoppedRaw === '1') return false;

    // Check if activation phase is complete: last phase email > 21 days ago
    const submittedAt = fields.ac_last_form_submitted_at;
    if (!submittedAt) return false;
    const submitted = new Date(submittedAt);
    const daysSinceSubmit = (today - submitted) / (1000 * 60 * 60 * 24);
    if (daysSinceSubmit < 23) return false; // 21 days activation + 2 day buffer

    return true;
  })
  .map(contact => {
    const fields = contact.fields?.all || {};
    const evergreen_position = Number(fields.ac_evergreen_position || 0);
    return {
      json: {
        mauticContactId: contact.id,
        contact_id: fields.ac_contact_id || '',
        evergreen_position,
        next_position: evergreen_position + 1,
        profile: fields.ac_last_profile || '',
        language: fields.ac_last_form_language || 'de'
      }
    };
  });
